CREATE TABLE IF NOT EXISTS _billing_invoice_status (
  invoice_id TEXT PRIMARY KEY,
  status TEXT NOT NULL
);
INSERT OR IGNORE INTO _billing_invoice_status(invoice_id, status)
SELECT id, 'open' FROM invoices;

